/**
 * Set up the copy-on-write diff file for a client.
 *
 * @param client The client to set copy-on-write up for; ->exportname,
 * ->exportsize and ->server must be set up already.
 * @return true on success, false on failure
 **/
static bool setup_cow(CLIENT *client) {
	const char *base;
	uint64_t npages;

	client->difffile = -1;
	client->difffilename = NULL;
	client->difmap = NULL;
	client->difffilelen = 0;

	base = strrchr(client->exportname, '/');
	base = base ? base + 1 : client->exportname;
	if(client->server->cowdir) {
		client->difffilename = g_strdup_printf("%s/%s.diff",
						       client->server->cowdir,
						       base);
	} else {
		client->difffilename = g_strdup_printf("%s.diff",
						       client->exportname);
	}

	client->difffile = open(client->difffilename,
				O_RDWR | O_CREAT | O_TRUNC, 0600);
	if(client->difffile == -1) {
		err_nonfatal("Could not create copy-on-write diff file %s: %m",
			     client->difffilename);
		return false;
	}

	if(client->server->flags & F_SPARSE) {
		/* Use a sparse file the size of the export, so that each
		 * page can be stored at its own offset. */
		if(ftruncate(client->difffile, client->exportsize) < 0) {
			err_nonfatal("Could not resize copy-on-write diff file %s: %m",
				     client->difffilename);
			return false;
		}
		client->difffilelen = client->exportsize;
	}

	npages = (client->exportsize + DIFFPAGESIZE - 1) / DIFFPAGESIZE;
	client->difmap = g_malloc(npages * sizeof(off_t));
	/* (off_t)-1, i.e. all bits set, marks a page as not present */
	memset(client->difmap, 0xFF, npages * sizeof(off_t));

	if(pthread_mutex_init(&client->diff_lock, NULL)) {
		msg(LOG_ERR, "Unable to initialize copy-on-write mutex");
		return false;
	}

	msg(LOG_INFO, "Using copy-on-write diff file %s", client->difffilename);
	return true;
}

/**
 * Tear down the copy-on-write diff file for a client: the diff file is
 * removed so that the writes made during this connection are discarded
 * and the master file is left untouched.
 *
 * @param client The client to tear copy-on-write down for
 **/
static void cleanup_cow(CLIENT *client) {
	if(client->difffile != -1) {
		close(client->difffile);
		client->difffile = -1;
	}
	if(client->difffilename) {
		unlink(client->difffilename);
		client->difffilename = NULL;
	}
	if(client->difmap) {
		g_free(client->difmap);
		client->difmap = NULL;
		pthread_mutex_destroy(&client->diff_lock);
	}
}

