+	if(client->difmap[page] != (off_t)-1)
+		return client->difmap[page];
+
+	if(client->server->flags & F_SPARSE) {
+		loc = (off_t)page * DIFFPAGESIZE;
+	} else {
+		loc = client->difffilelen;
+		client->difffilelen += DIFFPAGESIZE;
+	}
