+	if(!skip_master) {
+		got = 0;
+		while(got < DIFFPAGESIZE) {
+			ssize_t r = master_read(client,
+						(off_t)page * DIFFPAGESIZE + got,
+						pagebuf + got,
+						DIFFPAGESIZE - got);
