+				return (off_t)-1;
+			if(r == 0) {
+				/* Past the end of the master file; pad with
+				 * zeroes */
+				memset(pagebuf + got, 0, DIFFPAGESIZE - got);
+				break;
+			}
+			got += r;
+		}
+		if(pwrite(client->difffile, pagebuf, DIFFPAGESIZE, loc) != DIFFPAGESIZE)
+			return (off_t)-1;
