/**
 * Write data into the copy-on-write diff file rather than into the
 * master file. Any page that is not yet present in the diff file is
 * copied over from the master file first, so that the diff file always
 * holds a complete page.
 *
 * @param client The client we're serving for
 * @param a The offset where the write should start
 * @param buf The buffer to write from
 * @param len The length of buf
 * @param fua Flag to indicate 'Force Unit Access'
 * @return 0 on success, nonzero on failure
 **/
static int cow_write(CLIENT *client, off_t a, char *buf, size_t len, int fua) {
	pthread_mutex_lock(&client->diff_lock);
	while(len > 0) {
		uint64_t page = a / DIFFPAGESIZE;
		size_t off_in_page = a % DIFFPAGESIZE;
		size_t chunk = DIFFPAGESIZE - off_in_page;
		off_t loc;

		if(chunk > len)
			chunk = len;

		loc = cow_ensure_page(client, page,
				      (off_in_page == 0 && chunk == DIFFPAGESIZE));
		if(loc == (off_t)-1)
			goto err;

		if(pwrite(client->difffile, buf, chunk, loc + off_in_page) != (ssize_t)chunk)
			goto err;

		a += chunk;
		buf += chunk;
		len -= chunk;
	}
	if(client->server->flags & F_SYNC) {
		fsync(client->difffile);
	} else if(fua) {
		fdatasync(client->difffile);
	}
	pthread_mutex_unlock(&client->diff_lock);
	return 0;
err:
	pthread_mutex_unlock(&client->diff_lock);
	return -1;
}

