/**
 * Write an amount of bytes at a given offset into the copy-on-write
 * diff file, retrying until all data has been written.
 *
 * @param client The client we're serving for
 * @param loc The offset in the diff file where the write should start
 * @param buf The buffer to write from
 * @param len The length of buf
 * @return 0 on success, -1 on failure
 **/
static int diff_write_fully(CLIENT *client, off_t loc, const char *buf, size_t len) {
	while(len > 0) {
		ssize_t w = pwrite(client->difffile, buf, len, loc);
		if(w < 0)
			return -1;
		loc += w;
		buf += w;
		len -= w;
	}
	return 0;
}

/**
 * Make sure a given page is present in the copy-on-write diff file,
 * copying it over from the master file if it is not yet there.
 *
 * Must be called with client->diff_lock held.

